mapper.select:
SELECT dm.MODEL_ID, dm.MODEL_CODE, dm.MODEL_NAME, dm.MODEL_TYPE, CASE dm.MODEL_TYPE WHEN 'FINANCIAL' THEN '财务模型' WHEN 'RISK' THEN '风险模型' WHEN 'AUDIT' THEN '审计模型' ELSE dm.MODEL_TYPE END AS MODEL_TYPE_NAME, dm.BUSINESS_MEANING, dm.CALCULATION_LOGIC, dm.DATA_SOURCE_ID, ds.SOURCE_NAME AS DATA_SOURCE_NAME, dm.SQL_STATEMENT, dm.TEMPLATE_ID, st.TEMPLATE_NAME AS TEMPLATE_NAME, dm.PARAMETER_CONFIG, dm.VERSION, dm.STATUS, CASE dm.STATUS WHEN 'DRAFT' THEN '草稿' WHEN 'TESTING' THEN '测试中' WHEN 'PUBLISHED' THEN '已发布' ELSE dm.STATUS END AS STATUS_NAME, dm.IS_ENABLED, CASE dm.IS_ENABLED WHEN 'Y' THEN '启用' WHEN 'N' THEN '禁用' ELSE dm.IS_ENABLED END AS IS_ENABLED_NAME, dm.EXECUTION_COUNT, dm.LAST_EXECUTION_TIME, dm.EXECUTION_RESULT, CASE dm.EXECUTION_RESULT WHEN 'SUCCESS' THEN '成功' WHEN 'FAILED' THEN '失败' ELSE dm.EXECUTION_RESULT END AS EXECUTION_RESULT_NAME, dm.CREATE_USER, dm.CREATE_TIME, dm.UPDATE_USER, dm.UPDATE_TIME, CASE WHEN dm.STATUS = 'DRAFT' THEN 1 ELSE 0 END AS CAN_EDIT, CASE WHEN dm.STATUS != 'PUBLISHED' THEN 1 ELSE 0 END AS CAN_DELETE, 1 AS CAN_COPY, CASE WHEN dm.STATUS = 'DRAFT' THEN 1 ELSE 0 END AS CAN_PUBLISH, CASE WHEN dm.STATUS = 'PUBLISHED' THEN 1 ELSE 0 END AS CAN_ARCHIVE, CASE WHEN dm.STATUS = 'PUBLISHED' AND dm.IS_ENABLED = 'Y' THEN 1 ELSE 0 END AS CAN_EXECUTE, 1 AS CAN_TEST FROM TBL_DATA_MODEL dm LEFT JOIN TBL_DATA_SOURCE ds ON dm.DATA_SOURCE_ID = ds.SOURCE_ID LEFT JOIN TBL_SQL_TEMPLATE st ON dm.TEMPLATE_ID = st.TEMPLATE_ID
AND dm.MODEL_CODE LIKE '%' || #{query.modelCode} || '%'
AND dm.MODEL_NAME LIKE '%' || #{query.modelName} || '%'
AND dm.MODEL_TYPE = #{query.modelType}
AND dm.STATUS = #{query.status}
AND dm.DATA_SOURCE_ID = #{query.dataSourceId}
AND dm.IS_ENABLED = #{query.isEnabled}
AND dm.CREATE_USER = #{query.createUser}
AND dm.CREATE_TIME >= #{query.startTime}
AND dm.CREATE_TIME <= #{query.endTime}
ORDER BY dm.UPDATE_TIME DESC, dm.CREATE_TIME DESC

SELECT dm.MODEL_ID, dm.MODEL_CODE, dm.MODEL_NAME, dm.MODEL_TYPE, CASE dm.MODEL_TYPE WHEN 'FINANCIAL' THEN '财务模型' WHEN 'RISK' THEN '风险模型' WHEN 'AUDIT' THEN '审计模型' WHEN 'BUSINESS' THEN '业务模型' WHEN 'RISK_MONITOR' THEN 'RISK_MONITOR' WHEN 'COMBINATION' THEN 'COMBINATION' ELSE dm.MODEL_TYPE END AS MODEL_TYPE_NAME, NVL(dm.SOURCE_TYPE, 'MANUAL') AS SOURCE_TYPE, CASE NVL(dm.SOURCE_TYPE, 'MANUAL') WHEN 'MANUAL' THEN '手动创建' WHEN 'COMBINATION_SYNC' THEN '组合同步' WHEN 'TEMPLATE' THEN '模板生成' ELSE NVL(dm.SOURCE_TYPE, 'MANUAL') END AS SOURCE_TYPE_NAME, dm.SOURCE_COMBINATION_ID, ic.COMBINATION_NAME AS SOURCE_COMBINATION_NAME, dm.SOURCE_INDICATOR_CONFIG_ID, dm.SOURCE_INDICATOR_ID, dm.LAST_SYNC_TIME, dm.BUSINESS_MEANING, dm.CALCULATION_LOGIC, dm.DATA_SOURCE_ID, ds.SOURCE_NAME AS DATA_SOURCE_NAME, dm.SQL_STATEMENT, dm.TEMPLATE_ID, st.TEMPLATE_NAME AS TEMPLATE_NAME, dm.PARAMETER_CONFIG, dm.VERSION, dm.STATUS, CASE dm.STATUS WHEN 'DRAFT' THEN '草稿' WHEN 'TESTING' THEN '测试中' WHEN 'PUBLISHED' THEN '已发布' WHEN 'ARCHIVED' THEN '已归档' ELSE dm.STATUS END AS STATUS_NAME, dm.IS_ENABLED, CASE dm.IS_ENABLED WHEN 'Y' THEN '启用' WHEN 'N' THEN '禁用' ELSE dm.IS_ENABLED END AS IS_ENABLED_NAME, dm.EXECUTION_COUNT, dm.LAST_EXECUTION_TIME, dm.EXECUTION_RESULT, CASE dm.EXECUTION_RESULT WHEN 'SUCCESS' THEN '成功' WHEN 'FAILED' THEN '失败' WHEN 'TIMEOUT' THEN '超时' ELSE dm.EXECUTION_RESULT END AS EXECUTION_RESULT_NAME, dm.CREATE_USER, dm.CREATE_TIME, dm.UPDATE_USER, dm.UPDATE_TIME, -- 权限控制字段 CASE WHEN dm.STATUS = 'DRAFT' THEN 'true' ELSE 'false' END AS CAN_EDIT, CASE WHEN dm.STATUS = 'DRAFT' THEN 'true' ELSE 'false' END AS CAN_DELETE, 'true' AS CAN_COPY, CASE WHEN dm.STATUS = 'PUBLISHED' AND dm.IS_ENABLED = 'Y' THEN 'true' ELSE 'false' END AS CAN_EXECUTE, 'true' AS CAN_TEST, CASE WHEN dm.STATUS = 'DRAFT' THEN 'true' ELSE 'false' END AS CAN_PUBLISH, CASE WHEN dm.STATUS = 'PUBLISHED' THEN 'true' ELSE 'false' END AS CAN_ARCHIVE FROM TBL_DATA_MODEL dm LEFT JOIN TBL_DATA_SOURCE ds ON dm.DATA_SOURCE_ID = ds.SOURCE_ID LEFT JOIN TBL_SQL_TEMPLATE st ON dm.TEMPLATE_ID = st.TEMPLATE_ID LEFT JOIN TBL_INDICATOR_COMBINATION ic ON dm.SOURCE_COMBINATION_ID = ic.COMBINATION_ID
AND dm.MODEL_NAME LIKE CONCAT('%', #{query.modelName}, '%')
AND dm.MODEL_CODE = #{query.modelCode}
AND dm.MODEL_TYPE = #{query.modelType}
AND dm.DATA_SOURCE_ID = #{query.dataSourceId}
AND dm.STATUS = #{query.status}
AND dm.IS_ENABLED = #{query.isEnabled}
AND dm.CREATE_USER = #{query.createUser}
AND dm.CREATE_TIME >= #{query.startTime}
AND dm.CREATE_TIME <= #{query.endTime}
AND NVL(dm.SOURCE_TYPE, 'MANUAL') = #{query.sourceType}
AND dm.SOURCE_COMBINATION_ID = #{query.sourceCombinationId}
ORDER BY dm.UPDATE_TIME DESC, dm.CREATE_TIME DESC
